  1→package checkpoint
  2→
  3→import (
  4→	"context"
  5→	"crypto/sha256"
  6→	"errors"
  7→	"fmt"
  8→	"log/slog"
  9→	"os"
 10→	"strings"
 11→	"time"
 12→
 13→	"github.com/entireio/cli/cmd/entire/cli/agent"
 14→	"github.com/entireio/cli/cmd/entire/cli/agent/types"
 15→	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
 16→	"github.com/entireio/cli/cmd/entire/cli/logging"
 17→	"github.com/entireio/cli/cmd/entire/cli/paths"
 18→	"github.com/entireio/cli/cmd/entire/cli/validation"
 19→	"github.com/entireio/cli/cmd/entire/cli/versioninfo"
 20→	"github.com/entireio/cli/redact"
 21→
 22→	"github.com/go-git/go-git/v6/plumbing"
 23→	"github.com/go-git/go-git/v6/plumbing/filemode"
 24→	"github.com/go-git/go-git/v6/plumbing/object"
 25→)
 26→
 27→// WriteCommitted writes a committed checkpoint to both v2 refs:
 28→//   - /main: metadata and prompts (no raw transcript or content hash)
 29→//   - /full/current: raw transcript + content hash (replaces previous content)
 30→//
 31→// This is the public entry point for v2 dual-writes. The session index is
 32→// determined from the /main ref and passed to the /full/current write to
 33→// keep both refs consistent.
 34→func (s *V2GitStore) WriteCommitted(ctx context.Context, opts WriteCommittedOptions) error {
 35→	sessionIndex, err := s.writeCommittedMain(ctx, opts)
 36→	if err != nil {
 37→		return fmt.Errorf("v2 /main write failed: %w", err)
 38→	}
 39→
 40→	if err := s.writeCommittedFullTranscript(ctx, opts, sessionIndex); err != nil {
 41→		return fmt.Errorf("v2 /full/current write failed: %w", err)
 42→	}
 43→
 44→	return nil
 45→}
 46→
 47→// UpdateCommitted replaces the prompts and/or transcript for an existing v2 checkpoint.
 48→// Called at stop time to finalize checkpoints with the complete session transcript.
 49→//
 50→// On /main: replaces prompts (transcript is not stored there).
 51→// On /full/current: replaces the raw transcript (if provided).
 52→//
 53→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist on /main.
 54→func (s *V2GitStore) UpdateCommitted(ctx context.Context, opts UpdateCommittedOptions) error {
 55→	if opts.CheckpointID.IsEmpty() {
 56→		return errors.New("invalid update options: checkpoint ID is required")
 57→	}
 58→
 59→	sessionIndex, err := s.updateCommittedMain(ctx, opts)
 60→	if err != nil {
 61→		return fmt.Errorf("v2 /main update failed: %w", err)
 62→	}
 63→
 64→	if len(opts.Transcript) > 0 {
 65→		if err := s.updateCommittedFullTranscript(ctx, opts, sessionIndex); err != nil {
 66→			return fmt.Errorf("v2 /full/current update failed: %w", err)
 67→		}
 68→	}
 69→
 70→	return nil
 71→}
 72→
 73→// updateCommittedMain updates prompts on the /main ref for an existing checkpoint.
 74→// Returns the session index for coordination with /full/current.
 75→func (s *V2GitStore) updateCommittedMain(ctx context.Context, opts UpdateCommittedOptions) (int, error) {
 76→	refName := plumbing.ReferenceName(paths.V2MainRefName)
 77→	parentHash, rootTreeHash, err := s.getRefState(refName)
 78→	if err != nil {
 79→		return 0, ErrCheckpointNotFound
 80→	}
 81→
 82→	basePath := opts.CheckpointID.Path() + "/"
 83→	checkpointPath := opts.CheckpointID.Path()
 84→
 85→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
 86→	if err != nil {
 87→		return 0, err
 88→	}
 89→
 90→	// Read root summary to find session index
 91→	rootMetadataPath := basePath + paths.MetadataFileName
 92→	entry, exists := entries[rootMetadataPath]
 93→	if !exists {
 94→		return 0, ErrCheckpointNotFound
 95→	}
 96→
 97→	summary, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
 98→	if err != nil {
 99→		return 0, fmt.Errorf("failed to read checkpoint summary: %w", err)
100→	}
101→	if len(summary.Sessions) == 0 {
102→		return 0, ErrCheckpointNotFound
103→	}
104→
105→	// Find session index by ID, fall back to latest
106→	sessionIndex := s.gs.findSessionIndex(ctx, basePath, summary, entries, opts.SessionID)
107→	if sessionIndex >= len(summary.Sessions) {
108→		// findSessionIndex returns next-available when not found; fall back to latest
109→		sessionIndex = len(summary.Sessions) - 1
110→		logging.Debug(ctx, "v2 UpdateCommitted: session ID not found, falling back to latest",
111→			slog.String("session_id", opts.SessionID),
112→			slog.String("checkpoint_id", string(opts.CheckpointID)),
113→			slog.Int("fallback_index", sessionIndex),
114→		)
115→	}
116→
117→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
118→
119→	// Replace prompts
120→	if len(opts.Prompts) > 0 {
121→		promptContent := redact.String(strings.Join(opts.Prompts, "\n\n---\n\n"))
122→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
123→		if err != nil {
124→			return 0, fmt.Errorf("failed to create prompt blob: %w", err)
125→		}
126→		entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
127→			Name: sessionPath + paths.PromptFileName,
128→			Mode: filemode.Regular,
129→			Hash: blobHash,
130→		}
131→	}
132→
133→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
134→	if err != nil {
135→		return 0, err
136→	}
137→
138→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
139→	commitMsg := fmt.Sprintf("Finalize checkpoint: %s\n", opts.CheckpointID)
140→	if err := s.updateRef(refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail); err != nil {
141→		return 0, err
142→	}
143→
144→	return sessionIndex, nil
145→}
146→
147→// updateCommittedFullTranscript replaces the transcript for a specific checkpoint
148→// on /full/current while preserving other checkpoints' transcripts in the tree.
149→func (s *V2GitStore) updateCommittedFullTranscript(ctx context.Context, opts UpdateCommittedOptions, sessionIndex int) error {
150→	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
151→	if err := s.ensureRef(refName); err != nil {
152→		return fmt.Errorf("failed to ensure /full/current ref: %w", err)
153→	}
154→
155→	parentHash, rootTreeHash, err := s.getRefState(refName)
156→	if err != nil {
157→		return err
158→	}
159→
160→	basePath := opts.CheckpointID.Path() + "/"
161→	checkpointPath := opts.CheckpointID.Path()
162→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
163→
164→	// Read existing entries and replace transcript for this checkpoint only
165→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
166→	if err != nil {
167→		return err
168→	}
169→
170→	// Clear existing transcript entries at this session path before writing new ones
171→	for key := range entries {
172→		if strings.HasPrefix(key, sessionPath) {
173→			delete(entries, key)
174→		}
175→	}
176→
177→	redactedTranscript, err := s.writeTranscriptBlobs(ctx, opts.Transcript, opts.Agent, sessionPath, entries)
178→	if err != nil {
179→		return err
180→	}
181→
182→	if err := s.writeContentHash(redactedTranscript, sessionPath, entries); err != nil {
183→		return err
184→	}
185→
186→	// Splice into existing root tree (preserves other checkpoints' transcripts)
187→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
188→	if err != nil {
189→		return err
190→	}
191→
192→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
193→	commitMsg := fmt.Sprintf("Finalize checkpoint: %s\n", opts.CheckpointID)
194→	return s.updateRef(refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail)
195→}
196→
197→// writeCommittedMain writes metadata entries to the /main ref.
198→// This includes session metadata and prompts — but NOT the raw transcript
199→// (full.jsonl) or content hash (content_hash.txt), which go to /full/current.
200→// Returns the session index used, so the caller can pass it to writeCommittedFullTranscript.
201→func (s *V2GitStore) writeCommittedMain(ctx context.Context, opts WriteCommittedOptions) (int, error) {
202→	if err := validateWriteOpts(opts); err != nil {
203→		return 0, err
204→	}
205→
206→	refName := plumbing.ReferenceName(paths.V2MainRefName)
207→	if err := s.ensureRef(refName); err != nil {
208→		return 0, fmt.Errorf("failed to ensure /main ref: %w", err)
209→	}
210→
211→	parentHash, rootTreeHash, err := s.getRefState(refName)
212→	if err != nil {
213→		return 0, err
214→	}
215→
216→	basePath := opts.CheckpointID.Path() + "/"
217→	checkpointPath := opts.CheckpointID.Path()
218→
219→	// Read existing entries at this checkpoint's shard path
220→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
221→	if err != nil {
222→		return 0, err
223→	}
224→
225→	// Build main session entries (metadata, prompts — no transcript or content hash)
226→	sessionIndex, err := s.writeMainCheckpointEntries(ctx, opts, basePath, entries)
227→	if err != nil {
228→		return 0, err
229→	}
230→
231→	// Splice entries into root tree
232→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
233→	if err != nil {
234→		return 0, err
235→	}
236→
237→	commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
238→	if err := s.updateRef(refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
239→		return 0, err
240→	}
241→	return sessionIndex, nil
242→}
243→
244→// writeMainCheckpointEntries orchestrates writing session data to the /main ref.
245→// It mirrors GitStore.writeStandardCheckpointEntries but excludes raw transcript blobs.
246→// Returns the session index used, for coordination with writeCommittedFullTranscript.
247→func (s *V2GitStore) writeMainCheckpointEntries(ctx context.Context, opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) (int, error) {
248→	// Read existing summary to get current session count
249→	var existingSummary *CheckpointSummary
250→	metadataPath := basePath + paths.MetadataFileName
251→	if entry, exists := entries[metadataPath]; exists {
252→		existing, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
253→		if err == nil {
254→			existingSummary = existing
255→		}
256→	}
257→
258→	// Determine session index
259→	sessionIndex := s.gs.findSessionIndex(ctx, basePath, existingSummary, entries, opts.SessionID)
260→
261→	// Write session files (metadata and prompts — no transcript or content hash)
262→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
263→	sessionFilePaths, err := s.writeMainSessionToSubdirectory(opts, sessionPath, entries)
264→	if err != nil {
265→		return 0, err
266→	}
267→
268→	// Build the sessions array
269→	var sessions []SessionFilePaths
270→	if existingSummary != nil {
271→		sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
272→		copy(sessions, existingSummary.Sessions)
273→	} else {
274→		sessions = make([]SessionFilePaths, 1)
275→	}
276→	sessions[sessionIndex] = sessionFilePaths
277→
278→	// Write root CheckpointSummary
279→	if err := s.gs.writeCheckpointSummary(opts, basePath, entries, sessions); err != nil {
280→		return 0, err
281→	}
282→	return sessionIndex, nil
283→}
284→
285→// writeMainSessionToSubdirectory writes a single session's metadata, prompts, and
286→// content hash to a session subdirectory (0/, 1/, 2/, … indexed by session order
287→// within the checkpoint). Unlike the v1 equivalent, this does NOT write the raw
288→// transcript (full.jsonl) — that goes to /full/current.
289→func (s *V2GitStore) writeMainSessionToSubdirectory(opts WriteCommittedOptions, sessionPath string, entries map[string]object.TreeEntry) (SessionFilePaths, error) {
290→	filePaths := SessionFilePaths{}
291→
292→	// Clear existing entries at this session path
293→	for key := range entries {
294→		if strings.HasPrefix(key, sessionPath) {
295→			delete(entries, key)
296→		}
297→	}
298→
299→	// Write prompts
300→	if len(opts.Prompts) > 0 {
301→		promptContent := redact.String(strings.Join(opts.Prompts, "\n\n---\n\n"))
302→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
303→		if err != nil {
304→			return filePaths, err
305→		}
306→		entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
307→			Name: sessionPath + paths.PromptFileName,
308→			Mode: filemode.Regular,
309→			Hash: blobHash,
310→		}
311→		filePaths.Prompt = "/" + sessionPath + paths.PromptFileName
312→	}
313→
314→	// Write session metadata
315→	sessionMetadata := CommittedMetadata{
316→		CheckpointID:                opts.CheckpointID,
317→		SessionID:                   opts.SessionID,
318→		Strategy:                    opts.Strategy,
319→		CreatedAt:                   time.Now().UTC(),
320→		Branch:                      opts.Branch,
321→		CheckpointsCount:            opts.CheckpointsCount,
322→		FilesTouched:                opts.FilesTouched,
323→		Agent:                       opts.Agent,
324→		Model:                       opts.Model,
325→		TurnID:                      opts.TurnID,
326→		IsTask:                      opts.IsTask,
327→		ToolUseID:                   opts.ToolUseID,
328→		TranscriptIdentifierAtStart: opts.TranscriptIdentifierAtStart,
329→		CheckpointTranscriptStart:   opts.CheckpointTranscriptStart,
330→		TranscriptLinesAtStart:      opts.CheckpointTranscriptStart,
331→		TokenUsage:                  opts.TokenUsage,
332→		SessionMetrics:              opts.SessionMetrics,
333→		InitialAttribution:          opts.InitialAttribution,
334→		Summary:                     redactSummary(opts.Summary),
335→		CLIVersion:                  versioninfo.Version,
336→	}
337→
338→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(sessionMetadata, "", "  ")
339→	if err != nil {
340→		return filePaths, fmt.Errorf("failed to marshal session metadata: %w", err)
341→	}
342→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
343→	if err != nil {
344→		return filePaths, err
345→	}
346→	entries[sessionPath+paths.MetadataFileName] = object.TreeEntry{
347→		Name: sessionPath + paths.MetadataFileName,
348→		Mode: filemode.Regular,
349→		Hash: metadataHash,
350→	}
351→	filePaths.Metadata = "/" + sessionPath + paths.MetadataFileName
352→
353→	return filePaths, nil
354→}
355→
356→// writeContentHash computes and writes the content hash for already-redacted transcript bytes.
357→func (s *V2GitStore) writeContentHash(redactedTranscript []byte, sessionPath string, entries map[string]object.TreeEntry) error {
358→	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(redactedTranscript))
359→	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
360→	if err != nil {
361→		return err
362→	}
363→	entries[sessionPath+paths.ContentHashFileName] = object.TreeEntry{
364→		Name: sessionPath + paths.ContentHashFileName,
365→		Mode: filemode.Regular,
366→		Hash: hashBlob,
367→	}
368→	return nil
369→}
370→
371→// writeCommittedFullTranscript writes the raw transcript to the /full/current ref.
372→// Transcripts accumulate across checkpoints — each write splices into the existing
373→// tree. When the ref reaches capacity, generation rotation (future work) archives
374→// the current ref and starts a fresh one.
375→//
376→// sessionIndex is the session slot (0-based), determined by the caller to stay
377→// consistent with the /main ref's session numbering.
378→// This is a no-op if opts.Transcript is empty (and opts.TranscriptPath is unset).
379→func (s *V2GitStore) writeCommittedFullTranscript(ctx context.Context, opts WriteCommittedOptions, sessionIndex int) error {
380→	transcript := opts.Transcript
381→	if len(transcript) == 0 && opts.TranscriptPath != "" {
382→		var readErr error
383→		transcript, readErr = os.ReadFile(opts.TranscriptPath)
384→		if readErr != nil {
385→			transcript = nil
386→		}
387→	}
388→	if len(transcript) == 0 {
389→		return nil // No transcript to write
390→	}
391→
392→	if err := validateWriteOpts(opts); err != nil {
393→		return err
394→	}
395→
396→	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
397→	if err := s.ensureRef(refName); err != nil {
398→		return fmt.Errorf("failed to ensure /full/current ref: %w", err)
399→	}
400→
401→	parentHash, rootTreeHash, err := s.getRefState(refName)
402→	if err != nil {
403→		return err
404→	}
405→
406→	basePath := opts.CheckpointID.Path() + "/"
407→	checkpointPath := opts.CheckpointID.Path()
408→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
409→
